<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use RuntimeException;
use Throwable;

class ProductionStageController extends Controller
{
    private function run(callable $fn) { try { return $fn(); } catch (Throwable $e) { return response()->json(['error'=>$e->getMessage() ?: 'Request failed'],400); } }
    private function fail(string $m): never { throw new RuntimeException($m); }
    private function uid(Request $r): int { $u=DB::table('users')->where('email',$r->attributes->get('jwt_subject'))->first(); if(!$u)$this->fail('User not found'); $this->seedStages((int)$u->id); return $u->id; }
    private function owned(string $table,int $u,int $id,string $label): object { $x=DB::table($table)->where('id',$id)->where('user_id',$u)->first(); if(!$x)$this->fail($label.' not found'); return $x; }
    private function stage(int $u,int $id): object { return $this->owned('production_stages',$u,$id,'Stage'); }
    private function flowRow(int $u,int $id): object { return $this->owned('production_stage_flows',$u,$id,'Stage flow'); }
    private function component(int $u,int $id): object { return $this->owned('production_components',$u,$id,'Component'); }
    private function worker(int $u,int $id): object { $x=DB::table('workers')->where(['id'=>$id,'user_id'=>$u,'active'=>true])->first(); if(!$x)$this->fail('Worker not found'); return $x; }
    private function name($v,string $kind): string { $s=trim((string)($v??'')); if($s==='')$this->fail($kind.' name is required'); return $s; }
    private function unique(string $table,int $u,string $name,string $error,?int $except=null,bool $ci=false): void { $q=DB::table($table)->where('user_id',$u); $ci?$q->whereRaw('lower(name) = lower(?)',[$name]):$q->where('name',$name); if($except)$q->where('id','!=',$except); if($q->exists())$this->fail($error); }
    private function boolean($x): ?bool { return $x===null?null:filter_var($x,FILTER_VALIDATE_BOOLEAN); }
    private function stageDto(int $u,object $s): array { $count=DB::table('orders')->where('user_id',$u)->where('currentStage',$s->name)->count(); return ['id'=>$s->id,'name'=>$s->name,'displayOrder'=>$s->display_order,'active'=>(bool)$s->active,'usedInOrders'=>$count>0,'orderCount'=>$count]; }
    private function stageEntity(object $s): array { return ['id'=>$s->id,'name'=>$s->name,'displayOrder'=>$s->display_order,'active'=>(bool)$s->active,'createdAt'=>str_replace(' ','T',$s->created_at),'updatedAt'=>str_replace(' ','T',$s->updated_at)]; }
    private function flowDto(int $u,object $f): array { $steps=DB::table('production_stage_flow_steps as x')->join('production_stages as s','s.id','=','x.stage_id')->where('x.flow_id',$f->id)->orderBy('x.sequence')->orderBy('x.id')->get(['x.id','x.sequence','x.stage_id','s.name'])->map(fn($x)=>['id'=>$x->id,'sequence'=>$x->sequence,'stageId'=>$x->stage_id,'stageName'=>$x->name])->all(); $def=DB::table('users')->where('id',$u)->value('default_production_stage_flow_id'); return ['id'=>$f->id,'name'=>$f->name,'active'=>(bool)$f->active,'default'=>$def==$f->id,'stageCount'=>count($steps),'steps'=>$steps]; }
    private function componentDto(object $c): array { $ids=DB::table('production_stage_flow_components as m')->join('production_stage_flows as f','f.id','=','m.flow_id')->where('m.component_id',$c->id)->orderBy('f.name')->orderBy('m.display_order')->orderBy('m.id')->pluck('m.flow_id')->all(); return ['id'=>$c->id,'name'=>$c->name,'fixedRate'=>$c->fixed_rate,'active'=>(bool)$c->active,'flowIds'=>$ids]; }
    private function flowComponentsDto(int $u,int $id): array { $this->flowRow($u,$id); return DB::table('production_stage_flow_components as m')->join('production_components as c','c.id','=','m.component_id')->where(['m.user_id'=>$u,'m.flow_id'=>$id])->orderBy('m.display_order')->orderBy('m.id')->get(['m.id','m.flow_id','m.component_id','m.display_order','c.name','c.fixed_rate','c.active'])->map(fn($x)=>['id'=>$x->id,'flowId'=>$x->flow_id,'componentId'=>$x->component_id,'componentName'=>$x->name,'fixedRate'=>$x->fixed_rate,'active'=>(bool)$x->active,'displayOrder'=>$x->display_order])->all(); }
    private function mappingsDto(int $u,int $worker): array { return DB::table('worker_stage_mappings as m')->join('production_stages as s','s.id','=','m.stage_id')->where(['m.user_id'=>$u,'m.worker_id'=>$worker])->orderBy('s.display_order')->orderBy('s.id')->get(['m.id','m.worker_id','m.stage_id','m.rate_per_square_foot','s.name'])->map(fn($x)=>['id'=>$x->id,'workerId'=>$x->worker_id,'stageId'=>$x->stage_id,'stageName'=>$x->name,'ratePerSquareFoot'=>$x->rate_per_square_foot])->all(); }

    public function stages(Request $r) { return $this->run(function()use($r){$u=$this->uid($r);return ['stages'=>DB::table('production_stages')->where('user_id',$u)->orderBy('display_order')->orderBy('id')->get()->map(fn($s)=>$this->stageDto($u,$s))->all()];}); }
    private function seedStages(int $u): void { if(DB::table('production_stages')->where('user_id',$u)->exists())return;foreach(['Pending','Pause','Processing','Welding','Bending Cutting Steel','LED Processing','Glass Cutting With Frosted','Polishing','Dispatched for Coloring','Returned from Coloring','Completed','Delivered via Porter','Client Picked Up','Billed'] as $i=>$name)DB::table('production_stages')->insertOrIgnore(['user_id'=>$u,'name'=>$name,'display_order'=>$i+1,'active'=>true,'created_at'=>now(),'updated_at'=>now()]); }
    public function createStage(Request $r) { return $this->run(function()use($r){$u=$this->uid($r);$name=$this->name($r->input('name'),'Stage');$this->unique('production_stages',$u,$name,'Stage already exists');$order=$r->input('displayOrder')??((int)DB::table('production_stages')->where('user_id',$u)->max('display_order')+1);$id=DB::table('production_stages')->insertGetId(['user_id'=>$u,'name'=>$name,'display_order'=>$order,'active'=>true,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['stage'=>$this->stageEntity($this->stage($u,$id))],201);}); }
    public function updateStage(Request $r,int $id) { return $this->run(function()use($r,$id){$u=$this->uid($r);$s=$this->stage($u,$id);if(DB::table('orders')->where(['user_id'=>$u,'currentStage'=>$s->name])->exists())$this->fail('Stage is already used in orders and cannot be changed');$values=[];if($r->input('name')!==null){$name=$this->name($r->input('name'),'Stage');$this->unique('production_stages',$u,$name,'Stage already exists',$id);$values['name']=$name;}if($r->input('displayOrder')!==null)$values['display_order']=$r->input('displayOrder');if($r->input('active')!==null)$values['active']=$this->boolean($r->input('active'));if($values)DB::table('production_stages')->where('id',$id)->update($values+['updated_at'=>now()]);return ['stage'=>$this->stageEntity($this->stage($u,$id))];}); }
    public function deleteStage(Request $r,int $id) { return $this->run(function()use($r,$id){$u=$this->uid($r);$s=$this->stage($u,$id);if(DB::table('orders')->where(['user_id'=>$u,'currentStage'=>$s->name])->exists())$this->fail('Stage is already used in orders and cannot be deleted');DB::table('production_stages')->where('id',$id)->delete();return ['message'=>'Stage deleted'];}); }
    public function flows(Request $r) { return $this->run(function()use($r){$u=$this->uid($r);return ['flows'=>DB::table('production_stage_flows')->where(['user_id'=>$u,'active'=>true])->orderBy('name')->get()->map(fn($f)=>$this->flowDto($u,$f))->all()];}); }
    public function flow(Request $r,int $id) { return $this->run(fn()=>['flow'=>$this->flowDto($this->uid($r),$this->flowRow($this->uid($r),$id))]); }
    private function saveFlow(Request $r,?int $id) { return $this->run(function()use($r,$id){return DB::transaction(function()use($r,$id){$u=$this->uid($r);$name=$this->name($r->input('name'),'Flow');$ids=$r->input('stageIds');if(!is_array($ids)||count($ids)===0)$this->fail('Add at least one stage to the flow');if(count(array_unique($ids))!==count($ids))$this->fail('A stage can appear only once in a flow');foreach($ids as $sid)$this->stage($u,(int)$sid);if($id)$this->flowRow($u,$id);$this->unique('production_stage_flows',$u,$name,'Stage flow already exists',$id);$values=['name'=>$name,'active'=>$this->boolean($r->input('active'))??($id?DB::table('production_stage_flows')->where('id',$id)->value('active'):true),'updated_at'=>now()];if($id){DB::table('production_stage_flows')->where('id',$id)->update($values);DB::table('production_stage_flow_steps')->where('flow_id',$id)->delete();}else{$id=DB::table('production_stage_flows')->insertGetId($values+['user_id'=>$u,'created_at'=>now()]);}foreach($ids as $i=>$sid)DB::table('production_stage_flow_steps')->insert(['flow_id'=>$id,'stage_id'=>$sid,'sequence'=>$i+1]);return response()->json(['flow'=>$this->flowDto($u,$this->flowRow($u,$id))],$r->isMethod('post')?201:200);});}); }
    public function createFlow(Request $r) { return $this->saveFlow($r,null); }
    public function updateFlow(Request $r,int $id) { return $this->saveFlow($r,$id); }
    public function deleteFlow(Request $r,int $id) { return $this->run(function()use($r,$id){$u=$this->uid($r);$this->flowRow($u,$id);if(DB::table('users')->where(['id'=>$u,'default_production_stage_flow_id'=>$id])->exists())$this->fail('Default flow cannot be deleted');if(DB::table('orders')->where(['user_id'=>$u,'production_stage_flow_id'=>$id])->exists())$this->fail('Stage flow is already used by orders and cannot be deleted');DB::table('production_stage_flows')->where('id',$id)->update(['active'=>false,'updated_at'=>now()]);return ['message'=>'Stage flow deleted'];}); }
    public function components(Request $r) { return $this->run(function()use($r){$u=$this->uid($r);return ['components'=>DB::table('production_components')->where('user_id',$u)->orderBy('name')->orderBy('id')->get()->map(fn($c)=>$this->componentDto($c))->all()];}); }
    private function rate($v,string $label,int $scale): ?string {
        if($v===null||$v==='')return null;
        $raw=trim((string)$v);
        if(!preg_match('/^([+-]?)(\d+)(?:\.(\d*))?(?:[eE]([+-]?\d+))?$/',$raw,$m))$this->fail('Invalid rate');
        if($m[1]==='-' && preg_match('/[1-9]/',$m[2].($m[3]??'')))$this->fail($label.' cannot be negative');
        $digits=$m[2].($m[3]??'');
        $decimalPosition=strlen($m[2])+(int)($m[4]??0);
        if($decimalPosition<0)$digits=str_repeat('0',-$decimalPosition).$digits;
        elseif($decimalPosition>strlen($digits))$digits.=str_repeat('0',$decimalPosition-strlen($digits));
        $decimalPosition=max(0,$decimalPosition);
        $whole=substr($digits,0,$decimalPosition);
        $fraction=substr($digits,$decimalPosition);
        $whole=ltrim($whole,'0')?:'0';
        $retained=str_pad(substr($fraction,0,$scale),$scale,'0');
        $result=$whole.($scale?'.'.$retained:'');
        if(isset($fraction[$scale]) && $fraction[$scale]>='5')$result=bcadd($result,'0.'.str_repeat('0',$scale-1).'1',$scale);
        return $result;
    }
    public function createComponent(Request $r) { return $this->run(function()use($r){$u=$this->uid($r);$n=$this->name($r->input('name'),'Component');if(strlen($n)>150)$this->fail('Component name cannot exceed 150 characters');$this->unique('production_components',$u,$n,'Component already exists',null,true);$id=DB::table('production_components')->insertGetId(['user_id'=>$u,'name'=>$n,'fixed_rate'=>$this->rate($r->input('fixedRate'),'Component fixed rate',2)??'0.00','active'=>$this->boolean($r->input('active'))??true,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['component'=>$this->componentDto($this->component($u,$id))],201);}); }
    public function updateComponent(Request $r,int $id) { return $this->run(function()use($r,$id){$u=$this->uid($r);$c=$this->component($u,$id);$v=[];if($r->input('name')!==null){$n=$this->name($r->input('name'),'Component');if(strlen($n)>150)$this->fail('Component name cannot exceed 150 characters');$this->unique('production_components',$u,$n,'Component already exists',$id,true);$v['name']=$n;}if($r->input('fixedRate')!==null)$v['fixed_rate']=$this->rate($r->input('fixedRate'),'Component fixed rate',2);if($r->input('active')!==null){$active=$this->boolean($r->input('active'));if(!$active&&$c->active&&DB::table('production_stage_flow_components')->where(['user_id'=>$u,'component_id'=>$id])->exists())$this->fail('Remove this component from all flows before deactivating it');$v['active']=$active;}if($v)DB::table('production_components')->where('id',$id)->update($v+['updated_at'=>now()]);return ['component'=>$this->componentDto($this->component($u,$id))];}); }
    public function flowComponents(Request $r,int $id) { return $this->run(fn()=>['components'=>$this->flowComponentsDto($this->uid($r),$id)]); }
    public function updateFlowComponents(Request $r,int $id) { return $this->run(function()use($r,$id){return DB::transaction(function()use($r,$id){$u=$this->uid($r);$this->flowRow($u,$id);$ids=$r->input('componentIds',[]);if(!is_array($ids))$ids=[];if(count($ids)!==count(array_unique($ids)))$this->fail('A component cannot be mapped to the same flow more than once');foreach($ids as $cid){$c=$this->component($u,(int)$cid);if(!$c->active)$this->fail('Inactive components cannot be mapped to a flow');}DB::table('production_stage_flow_components')->where(['user_id'=>$u,'flow_id'=>$id])->delete();foreach($ids as $i=>$cid)DB::table('production_stage_flow_components')->insert(['user_id'=>$u,'flow_id'=>$id,'component_id'=>$cid,'display_order'=>$i+1]);return ['components'=>$this->flowComponentsDto($u,$id)];});}); }
    public function settings(Request $r) { return $this->run(function()use($r){$u=$this->uid($r);$id=DB::table('users')->where('id',$u)->value('default_production_stage_flow_id');return ['defaultFlowId'=>$id,'defaultFlowName'=>$id?DB::table('production_stage_flows')->where('id',$id)->value('name'):null];}); }
    public function updateSettings(Request $r) { return $this->run(function()use($r){$u=$this->uid($r);$id=$r->input('defaultFlowId');if($id!==null&&$id!=='')$this->flowRow($u,(int)$id);DB::table('users')->where('id',$u)->update(['default_production_stage_flow_id'=>$id?:null]);return $this->settings($r);}); }
    public function workerStageMappings(Request $r,int $id) { return $this->run(function()use($r,$id){$u=$this->uid($r);$this->worker($u,$id);return ['mappings'=>$this->mappingsDto($u,$id)];}); }
    public function updateWorkerStageMappings(Request $r,int $id) { return $this->run(function()use($r,$id){return DB::transaction(function()use($r,$id){$u=$this->uid($r);$this->worker($u,$id);$rows=$r->input('mappings',[]);if(!is_array($rows))$this->fail('mappings must be a list');$seen=[];$prepared=[];foreach($rows as $row){if(!is_array($row))$this->fail('Each mapping must be an object');$sid=$row['stageId']??null;if($sid===null||$sid==='')$this->fail('stageId is required');if(in_array((int)$sid,$seen,true))$this->fail('Stage cannot be assigned more than once to the same worker');$seen[]=(int)$sid;$s=$this->stage($u,(int)$sid);if(!$s->active)$this->fail('Inactive stages cannot be assigned');$prepared[]=['user_id'=>$u,'worker_id'=>$id,'stage_id'=>$sid,'rate_per_square_foot'=>$this->rate($row['ratePerSquareFoot']??null,'Worker stage rate',4),'created_at'=>now(),'updated_at'=>now()];}DB::table('worker_stage_mappings')->where(['user_id'=>$u,'worker_id'=>$id])->delete();foreach($prepared as $row)DB::table('worker_stage_mappings')->insert($row);return ['mappings'=>$this->mappingsDto($u,$id)];});}); }
}
